import {checkinLinks} from './checkin.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let trips=[],selectedEmail='',preview=false;
const message=s=>document.querySelector('#portalMessage').textContent=s;
async function api(path,options){const response=await fetch(path,{...options,headers:{'Content-Type':'application/json'},cache:'no-store'});const result=await response.json();if(!response.ok)throw Error(result.error||'No s’ha pogut carregar.');return result;}
function render(){document.querySelector('#portal').innerHTML=trips.length?trips.map(t=>{const p=t.person,done=(t.feedback.checkin||p.checkin)==='Fet',seen=t.feedback.seen_revision===t.revision;return `<article><div class="readiness-banner"><div><span class="eyebrow">EL TEU VIATGE</span><h1>${esc(t.name)}</h1><p>${esc(p.name)} · ${esc(p.role)}</p><p>${esc(t.start)} — ${esc(t.end)} · ${esc(t.destination)}</p></div></div><section class="panel portal-confirmation"><p>${seen?'✓ Has consultat aquesta versió del viatge.':'! Tens informació del viatge per revisar.'}</p><div class="actions"><button class="button secondary" ${seen?'hidden':''} data-action="seen" data-id="${esc(t.id)}">He vist el meu viatge</button>${p.travelMode!=='Cotxe'&&p.checkin!=='No cal'?`<button class="button" data-action="checkin" data-id="${esc(t.id)}">${done?'✓ Check-in fet · tornar a pendent':'Confirmar check-in dels vols'}</button>`:''}</div></section><section class="panel"><h2>${p.travelMode==='Cotxe'?'Viatge amb cotxe':'Els meus vols'}</h2>${p.travelMode==='Cotxe'?'<p>Consulta el transport i els horaris de sortida a continuació.</p>':p.journeys?.length?p.journeys.map(s=>`<div class="person-journey"><p class="route">${esc(s.origin)} → ${esc(s.destination)}</p><p>${esc(s.service)} · Sortida: ${esc(s.departure||'Pendent')}<br>Arribada: ${esc(s.arrival||'Pendent')}</p>${s.pending||s.stale?'<p class="status">Pendent de revisió de coordinació</p>':''}</div>`).join(''):'<p>Coordinació encara no ha associat els teus vols.</p>'}</section>${p.travelMode!=='Cotxe'?`<details class="panel simple-details"><summary>Check-in · localitzador i email</summary>${p.bookings?.length?p.bookings.map(b=>`<div class="person-journey"><h3>${esc(b.provider||'Reserva')}</h3><dl class="detail-list"><div><dt>Localitzador</dt><dd class="copyable">${esc(b.reference||'Pendent')}</dd></div><div><dt>Email de compra</dt><dd class="copyable">${esc(b.email||'Pendent')}</dd></div></dl>${checkinLinks[b.provider]?`<a class="button secondary" href="${esc(checkinLinks[b.provider])}" target="_blank" rel="noopener noreferrer">Obrir ${esc(b.provider)} ↗</a>`:''}</div>`).join(''):'<p>Reserva pendent d’associar.</p>'}</details>`:''}${(p.transports||[]).map(v=>`<section class="panel"><h2>${esc(v.direction)} · ${v.isDriver?'El teu vehicle':'Qui em recull?'}</h2>${v.name?`<p class="route">${esc(v.name)}</p><dl class="detail-list"><div><dt>Conductor</dt><dd>${esc(v.driver||'Pendent')}${v.phone?` · <a href="tel:${esc(v.phone.replace(/[^+0-9]/g,''))}">${esc(v.phone)}</a>`:''}</dd></div><div><dt>Sortida</dt><dd>${esc(v.origin||'Pendent')} · ${esc(v.departure||'Hora pendent')}</dd></div><div><dt>Recollida</dt><dd>${esc(v.pickupLocation||'Lloc pendent')} · ${esc(v.pickupTime||'Hora pendent')}</dd></div></dl>`:'<p>Vehicle pendent d’assignar.</p>'}</section>`).join('')}<details class="panel simple-details"><summary>Allotjament</summary><p>${esc(t.hotel||'Pendent de confirmar')}</p>${t.hotel?`<a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(t.hotel)}" target="_blank" rel="noopener noreferrer">Obrir al mapa ↗</a>`:''}</details>${p.notes?`<section class="panel"><h2>Notes per al teu viatge</h2><p style="white-space:pre-wrap">${esc(p.notes)}</p></section>`:''}<p>Coordinació: ${esc(t.coordinator||'Responsable del viatge')} · ${esc(t.phone||'')}</p><p class="small muted">Actualitzat: ${esc(new Date(t.updatedAt).toLocaleString('ca-ES'))}</p></article>`}).join(''):'<section class="panel"><h1>Encara no tens viatges assignats</h1><p>Demana a coordinació que comprovi el teu email personal i comparteixi el viatge.</p></section>'}
async function load(){if(!selectedEmail)return;const data=await api('/api/my-trips',{method:'POST',body:JSON.stringify({email:selectedEmail})});trips=data.trips;preview=!!data.preview;render();document.querySelector('#emailEntry').hidden=!!trips.length;document.querySelector('#changeEmail').hidden=!trips.length;document.querySelector('#previewNotice').hidden=!preview;document.querySelector('#refreshPortal').hidden=!trips.length;if(preview)document.querySelectorAll('#portal [data-action]').forEach(b=>b.disabled=true);}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b||preview)return;const trip=trips.find(t=>t.id===b.dataset.id);if(!trip)return;b.disabled=true;try{await api('/api/my-trips/'+encodeURIComponent(trip.id)+'/feedback',{method:'POST',body:JSON.stringify({action:b.dataset.action,revision:trip.revision,checkin:(trip.feedback.checkin||trip.person.checkin)==='Fet'?'Pendent':'Fet'})});await load();message('Confirmació guardada.')}catch(e){message(e.message);b.disabled=false}});
document.querySelector('#emailForm').onsubmit=async event=>{event.preventDefault();const button=document.querySelector('#emailSubmit');selectedEmail=document.querySelector('#athleteEmail').value.trim().toLowerCase();trips=[];preview=false;document.querySelector('#portal').innerHTML='';document.querySelector('#refreshPortal').hidden=true;document.querySelector('#previewNotice').hidden=true;message('Buscant el teu viatge…');button.disabled=true;try{await load();message('')}catch(e){message(e.message)}finally{button.disabled=false}};
api('/api/me').then(user=>{document.querySelector('#sessionHint').textContent=user.admin?'Coordinació: pots consultar la vista prèvia introduint l’email d’un participant.':'Sessió verificada: '+user.email;}).catch(e=>message(e.message));

document.querySelector('#refreshPortal').onclick=()=>load().then(()=>message('Viatge actualitzat.')).catch(e=>message(e.message));

document.querySelector('#changeEmail').onclick=()=>{document.querySelector('#emailEntry').hidden=false;document.querySelector('#athleteEmail').focus();};
